-- Clarify that 6,912 NIS is not a universal ceiling for every payment type.
-- Official BTL old-age income-supplement rules checked 2026-09-17.

insert into public.sources (slug, publisher, title, url, language, is_official, is_published, checked_on) values
  ('btl-old-age-income-supplement-eligibility', 'Битуах Леуми', 'Условия права на доплату до прожиточного минимума к пособию по старости', 'https://www.btl.gov.il/BENEFITS/OLD_AGE/HASHHACHZ/Pages/tnaiZakautTosefet.aspx', 'he', true, true, '2026-09-17')
on conflict (slug) do update set
  title=excluded.title,
  url=excluded.url,
  language=excluded.language,
  is_official=excluded.is_official,
  is_published=true,
  checked_on=excluded.checked_on;

update public.knowledge_cards k
set source_id = s.id,
    title = 'Как разные доходы влияют на доплату к пособию по старости в 2026 году',
    short_answer = 'Сумма 6 912 шекелей для пары младше 70 лет относится к случаю, когда учитываемый доход состоит только из пособия по старости и/или пособия по потере кормильца; это не универсальный потолок для простой суммы всех выплат семьи.',
    answer = 'Битуах Леуми проверяет разные виды дохода по разным правилам. Для пары младше 70 лет сумма 6 912 шекелей с 01.01.2026 относится к случаю, когда доход состоит только из пособия по старости и/или пособия по потере кормильца. Доход от работы, пенсионные выплаты, капитал, имущество и финансовые активы оцениваются по отдельным правилам. Поэтому нельзя просто сложить любые пособия и другие поступления семьи и сравнить результат с 6 912. Нужно сначала определить вид каждого дохода, а затем применить правило для этой категории.',
    steps = array['Разделите все поступления обоих супругов по видам: пособие по старости/потере кормильца, работа, пенсия, страховые выплаты, другие пособия, имущество и финансовые активы.','Не используйте 6 912 шекелей как общий потолок для суммы всех этих категорий.','Для финансовых активов отдельно рассчитайте условный доход по правилам Битуах Леуми.','Для итоговой проверки используйте официальный калькулятор или письменный расчёт Битуах Леуми.'],
    documents = array['Решения Битуах Леуми о пособиях','Подтверждения пенсионных и страховых выплат','Сведения о финансовых активах'],
    follow_up_questions = array['Что представляет собой страховая выплата и из какого источника она выплачивается?'],
    caveats = array['6 912 шекелей — не универсальный предел для простой суммы всех выплат семьи.','Чтобы сделать окончательный вывод, нужно знать правовую категорию каждого поступления.'],
    keywords = array['социальная надбавка','доплата до прожиточного минимума','6912','6 912','пособие по старости','вид дохода','пара'],
    search_text = 'социальная надбавка доплата до прожиточного минимума 6912 6 912 пара пособие по старости инвалидность особые услуги страховая выплата виды доходов нельзя просто сложить все выплаты 2026',
    embedding = null,
    reviewed_on = '2026-09-17',
    updated_at = now()
from public.sources s
where k.slug='old-age-income-supplement-2026'
  and s.slug='btl-old-age-income-supplement-eligibility';

update public.knowledge_cards
set short_answer = 'Доплата до прожиточного минимума открывает некоторые дополнительные льготы, но отсутствие такой доплаты не означает отсутствие всех льгот пожилого гражданина.',
    answer = 'Некоторые льготы действительно связаны именно с получением доплаты до прожиточного минимума, например определённые скидки на электричество. Но другие права пожилых граждан, включая отдельные варианты скидки на арнону, могут существовать и без этой доплаты. Поэтому нужно проверять каждую льготу отдельно, а не использовать наличие доплаты как универсальное условие для всех скидок.',
    steps = array['Уточните, назначена ли доплата до прожиточного минимума.','Отдельно проверьте конкретную льготу: арнона, электричество, вода или другую.','Не делайте вывод об отсутствии всех льгот только потому, что доплата не назначена.'],
    caveats = array['У каждой льготы собственные условия.','Муниципальные скидки могут зависеть от местных правил и дохода.'],
    keywords = array['скидки пенсионерам','социальная надбавка','льготы','пособие по старости','арнона','электричество'],
    search_text = 'пожилой гражданин скидки льготы пособие по старости социальная надбавка доплата прожиточный минимум не все льготы требуют доплату арнона электричество',
    embedding = null,
    reviewed_on='2026-09-17',
    updated_at=now()
where slug='old-age-supplement-benefits';